(function(){let order=null;try{order=JSON.parse(sessionStorage.getItem("todayFridgeLastOrder")||"null")}catch(_){}if(!order){location.replace("./order-history.html");return}const transfer=order.paymentType==="transfer";document.getElementById("complete-guide").textContent=transfer?"아래 계좌로 입금하면 확인 후 수령증이 활성화됩니다.":"매장에서 결제한 뒤 상품을 수령해 주세요.";document.getElementById("complete-summary").innerHTML=`<div><span>신청 상품</span><strong>${order.productName||"-"}</strong></div><div><span>수령 희망일</span><strong>${order.pickupDate||"-"} · ${order.pickupTimeLabel||"-"}</strong></div><div><span>결제 방식</span><strong>${transfer?"계좌이체":"현장결제"}</strong></div>`;if(transfer){document.getElementById("bank-box").hidden=false;document.getElementById("bank-amount").textContent=`${Number(order.totalAmount||order.total_amount||0).toLocaleString("ko-KR")}원`;document.getElementById("complete-note").textContent="입금 확인 전에는 수령 확인증에 상품이 표시되지 않습니다. 입금 확인이 완료되면 알림으로 알려드릴게요."}else{document.getElementById("complete-note").textContent="상품 입고가 완료되면 수령 확인증에서 키오스크 결제용 바코드를 확인할 수 있습니다."}})();
